import{_ as e,c as a,o as r,a1 as n}from"./chunks/framework.DKHw8SZo.js";const p=JSON.parse('{"title":"Samspelet mellan klient och server.","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/3-web/client-server.md","filePath":"web1/3-web/client-server.md"}'),t={name:"web1/3-web/client-server.md"},l=n('<h1 id="samspelet-mellan-klient-och-server" tabindex="-1">Samspelet mellan klient och server. <a class="header-anchor" href="#samspelet-mellan-klient-och-server" aria-label="Permalink to &quot;Samspelet mellan klient och server.&quot;">​</a></h1><p>När du surfar på internet eller använder en webbapp sker ett samspel mellan en klient (t.ex. din webbläsare) och en server (en dator som hanterar och skickar data).</p><h2 id="vad-ar-en-klient" tabindex="-1">Vad är en klient? <a class="header-anchor" href="#vad-ar-en-klient" aria-label="Permalink to &quot;Vad är en klient?&quot;">​</a></h2><p>En klient är en enhet eller ett program som begär information från en server. Exempel på klienter är:</p><ul><li>Webbläsare (Google Chrome, Firefox, Safari)</li><li>Mobilappar</li><li>Andra program som hämtar data från internet</li></ul><p>När du skriver in en webbadress i webbläsaren skickas en begäran (request) till en server för att hämta webbplatsens innehåll.</p><br><h2 id="vad-ar-en-server" tabindex="-1">Vad är en server? <a class="header-anchor" href="#vad-ar-en-server" aria-label="Permalink to &quot;Vad är en server?&quot;">​</a></h2><p>En server är en kraftfull dator som lagrar och hanterar webbsidor, databaser och andra resurser. Servern tar emot begäran från klienten och skickar tillbaka rätt data som svar (response). Exempel på servrar är:</p><ul><li>Webbservrar (Apache, Nginx, IIS)</li><li>Databasservrar (MySQL, PostgreSQL)</li><li>API-servrar</li></ul><br><h2 id="hur-fungerar-samspelet" tabindex="-1">Hur fungerar samspelet? <a class="header-anchor" href="#hur-fungerar-samspelet" aria-label="Permalink to &quot;Hur fungerar samspelet?&quot;">​</a></h2><ol><li>Klienten skickar en begäran – När du besöker en webbplats, skickar webbläsaren en begäran till servern via HTTP eller HTTPS.</li><li>Servern behandlar begäran – Servern letar upp rätt resurs (t.ex. en HTML-sida eller en bild).</li><li>Servern skickar ett svar – Webbsidan skickas tillbaka till klienten, ofta i form av HTML, CSS och JavaScript.</li><li>Klienten visar webbsidan – Webbläsaren tolkar koden och visar sidan för användaren.</li></ol><br><h2 id="dynamiska-och-statiska-webbplatser" tabindex="-1">Dynamiska och statiska webbplatser <a class="header-anchor" href="#dynamiska-och-statiska-webbplatser" aria-label="Permalink to &quot;Dynamiska och statiska webbplatser&quot;">​</a></h2><ul><li>Statisk webbplats – Servern skickar färdiga HTML-filer utan förändring.</li><li>Dynamisk webbplats – Servern skapar innehållet vid varje begäran, ofta med hjälp av databaser och programmeringsspråk som PHP, Python eller Node.js.</li></ul><br><h2 id="ajax-och-realtidskommunikation" tabindex="-1">AJAX och realtidskommunikation <a class="header-anchor" href="#ajax-och-realtidskommunikation" aria-label="Permalink to &quot;AJAX och realtidskommunikation&quot;">​</a></h2><p>Med AJAX (Asynchronous JavaScript and XML) kan klienten hämta data från servern utan att ladda om sidan. Exempel på detta är:</p><ul><li>Sökmotorers autoslutförande</li><li>Sociala medier-flöden</li><li>Chattfunktioner</li></ul><br><h2 id="sammanfattning" tabindex="-1">Sammanfattning <a class="header-anchor" href="#sammanfattning" aria-label="Permalink to &quot;Sammanfattning&quot;">​</a></h2><ul><li>Klienten (t.ex. en webbläsare) skickar begäran.</li><li>Servern tar emot och behandlar begäran.</li><li>Servern svarar med data (HTML, JSON, bilder, etc.).</li><li>Klienten visar informationen för användaren.</li></ul><p>Detta samspel är grunden för hur webben fungerar och är viktigt att förstå i webbutveckling!</p><br><p>😎 👊 👍</p>',26),i=[l];function s(o,d,b,h,m,c){return r(),a("div",null,i)}const u=e(t,[["render",s]]);export{p as __pageData,u as default};
